        q=a.loc[lo:hi,'ic']; print(lo+'-'+hi,'n',len(q),'mean %.5f icir %.5f'%(q.mean(),q.mean()/q.std(ddof=1)))
r=f.rank(axis=1,pct=True); print('turnover',r.diff().abs().mean().mean())
f.to_csv('scripts/miner_1_20260827_breakout60_signal.csv')

